mapper.select:
select t.authority as authority, t.alias as alias, (case when t.group_id is null then 'default' else t.group_id end) as groupId
from la_roles t where enabled = 1

    and t.authority not in #{item}



        and t.tenant_id = #{tenantId}


        and t.tenant_id is null


order by t.alias

select t.authority as authority, t.alias as alias, t.tenant_id as tenantId, t.enabled as enabled, t.role_type as roleType, t.data_type as dataType, t.icon as icon, t.remarks as remarks, t.created_at as createdAt,
       case when t.group_id is null then 'default' else t.group_id end as groupId
from la_roles t


        and t.authority not in #{item}


        and t.group_id = #{parameters.groupId}


        and t.alias like #{parameters.alias}



            and t.tenant_id = #{parameters.tenantId}


            and t.tenant_id is null



order by t.alias

select authority as authority, alias as alias, role_type as roleType, data_type as dataType, enabled as enabled, icon as icon, remarks as remarks, created_at as createdAt,
       case when group_id is null then 'default' else group_id end as groupId
from la_roles where authority = #{authority}

mapper.delete:
delete from la_role_resources where authority = #{authority}
and resource_id in

    #{item}

mapper.select:
select id from la_resources t
inner join la_role_resources tr on t.id = tr.resource_id and tr.authority = #{authority}


        t.parent_id is null


        t.parent_id = #{pid}

select t.id, t.name, t.parent_id, max(case when t4.resource_id is not null then 1 else 0 end) as checked, count(t2.id) as counts, sum(case when t3.resource_id is null then 0 else 1 end) as existed from la_resources t left join la_resources t2 on t2.parent_id = t.id left join la_organization_resources t3 on t3.resource_id = t2.id and t3.organization_id = #{organizationid} left join la_organization_resources t4 on t4.resource_id = t.id and t4.organization_id = #{organizationid}
t.parent_id is null
t.parent_id = #{pid}
group by t.id, t.name, t.parent_id, t.order_no order by t.order_no

select distinct t.id, t.res_name, t.parent_id, t.res_level, t.res_type, t.icon, t.application, (case when t3.resource_id is not null then 1 else 0 end ) as checked, t.order_no from la_resources t
inner join la_role_resources t2 on t2.resource_id = t.id
left join la_role_resources t3 on t3.resource_id = t.id and t3.authority = #{parameters.authority} where t.is_dev = 0 and t.res_type != 0 and t.res_mode = #{parameters.mode}
and t.application = #{parameters.application}
and t2.authority in
#{item}
order by t.res_level, t.parent_id, t.order_no

